import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

conv2d_source = r"""
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

#define TILE 16
#define OC_TILE 16
#define WTILE 4
__global__ void conv2d_forward_kernel(
    const float* __restrict__ input,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float* __restrict__ output,
    int N, int C_in, int H_in, int W_in,
    int C_out, int K, int stride, int padding,
    int H_out, int W_out,
    int patch_size,
    int oc_groups)
{
    extern __shared__ float smem[];
    int tile_col = blockIdx.x;
    int tile_row = blockIdx.y;
    int n = blockIdx.z;
    int tile_h = tile_row * TILE;
    int tile_w = tile_col * TILE;
    int ty = threadIdx.y;
    int tx = threadIdx.x;
    int oh = tile_h + ty;
    int ow_base = tile_w + tx * WTILE;
    int h_in_start = tile_h * stride - padding;
    int w_in_start = tile_w * stride - padding;
    bool valid_row = (oh < H_out);
    int patch_elems = patch_size * patch_size;
    int tid = ty * blockDim.x + tx;
    int num_threads = blockDim.x * blockDim.y;
    int kk = K * K;
    float* smem_patch = smem;
    float* smem_weight = smem + (size_t)C_in * patch_elems;
    // Load the full multi-channel input patch once; it is reused
    // across all output-channel groups processed by this block.
    int total_patch_elems = C_in * patch_elems;
    for (int idx = tid; idx < total_patch_elems; idx += num_threads) {
        int ic = idx / patch_elems;
        int rem = idx % patch_elems;
        int ph = rem / patch_size;
        int pw = rem % patch_size;
        int h_in = h_in_start + ph;
        int w_in = w_in_start + pw;
        float val = 0.0f;
        if (h_in >= 0 && h_in < H_in && w_in >= 0 && w_in < W_in) {
            const float* input_ptr = input + ((n * C_in + ic) * H_in) * W_in;
            val = input_ptr[h_in * W_in + w_in];
        }
        smem_patch[idx] = val;
    }
    __syncthreads();
    int weight_elems = OC_TILE * C_in * kk;
    for (int oc_group = 0; oc_group < oc_groups; ++oc_group) {
        int oc_start = oc_group * OC_TILE;
        for (int idx = tid; idx < weight_elems; idx += num_threads) {
            int oc_off = idx / (C_in * kk);
            int rem = idx % (C_in * kk);
            int ic = rem / kk;
            int within = rem % kk;
            int oc = oc_start + oc_off;
            float wval = 0.0f;
            if (oc < C_out) {
                wval = weight[((oc * C_in + ic) * kk) + within];
            }
            smem_weight[idx] = wval;
        }
        __syncthreads();
        if (valid_row) {
            float sum[OC_TILE][WTILE];
            #pragma unroll
            for (int i = 0; i < OC_TILE; ++i) {
                #pragma unroll
                for (int j = 0; j < WTILE; ++j) sum[i][j] = 0.0f;
            }
            #pragma unroll
            for (int oc_off = 0; oc_off < OC_TILE; ++oc_off) {
                float local_sum[WTILE];
                #pragma unroll
                for (int j = 0; j < WTILE; ++j) local_sum[j] = 0.0f;
                for (int ic = 0; ic < C_in; ++ic) {
                    const float* smem_row_base = smem_patch + ic * patch_elems;
                    const float* weight_ptr = smem_weight + (oc_off * C_in + ic) * kk;
                    for (int kh = 0; kh < K; ++kh) {
                        int ph = ty * stride + kh;
                        const float* smem_row = smem_row_base + ph * patch_size;
                        const float* weight_row = weight_ptr + kh * K;
                        for (int kw = 0; kw < K; ++kw) {
                            float wv = weight_row[kw];
                            #pragma unroll
                            for (int j = 0; j < WTILE; ++j) {
                                int pw = (tx * WTILE + j) * stride + kw;
                                local_sum[j] += smem_row[pw] * wv;
                            }
                        }
                    }
                }
                #pragma unroll
                for (int j = 0; j < WTILE; ++j) sum[oc_off][j] = local_sum[j];
            }
            #pragma unroll
            for (int j = 0; j < WTILE; ++j) {
                int ow = ow_base + j;
                if (ow < W_out) {
                    #pragma unroll
                    for (int oc_off = 0; oc_off < OC_TILE; ++oc_off) {
                        int oc = oc_start + oc_off;
                        if (oc < C_out) {
                            float result = sum[oc_off][j] + bias[oc];
                            int out_idx = ((n * C_out + oc) * H_out + oh) * W_out + ow;
                            output[out_idx] = result;
                        }
                    }
                }
            }
        }
        __syncthreads();
    }
}
torch::Tensor conv2d_forward_cuda(
    torch::Tensor input,
    torch::Tensor weight,
    torch::Tensor bias,
    int stride,
    int padding)
{
    const int N = input.size(0);
    const int C_in = input.size(1);
    const int H_in = input.size(2);
    const int W_in = input.size(3);
    const int C_out = weight.size(0);
    const int K = weight.size(2);
    const int H_out = (H_in + 2 * padding - K) / stride + 1;
    const int W_out = (W_in + 2 * padding - K) / stride + 1;
    auto output = torch::empty({N, C_out, H_out, W_out}, input.options());
    int patch_size = (TILE - 1) * stride + K;
    int kk = K * K;
    size_t smem_bytes = (size_t)C_in * patch_size * patch_size * sizeof(float)
                       + (size_t)OC_TILE * C_in * kk * sizeof(float);
    int oc_groups = (C_out + OC_TILE - 1) / OC_TILE;
    dim3 threads(TILE / WTILE, TILE);
    dim3 blocks(
        (W_out + TILE - 1) / TILE,
        (H_out + TILE - 1) / TILE,
        N
    );
    if (smem_bytes > 48 * 1024) {
        cudaFuncSetAttribute(
            conv2d_forward_kernel,
            cudaFuncAttributeMaxDynamicSharedMemorySize,
            smem_bytes);
    }
    conv2d_forward_kernel<<<blocks, threads, smem_bytes>>>(
        input.data_ptr<float>(),
        weight.data_ptr<float>(),
        bias.data_ptr<float>(),
        output.data_ptr<float>(),
        N, C_in, H_in, W_in,
        C_out, K, stride, padding,
        H_out, W_out,
        patch_size,
        oc_groups
    );
    return output;
}
"""

conv2d_cpp_source = r"""
torch::Tensor conv2d_forward_cuda(
    torch::Tensor input,
    torch::Tensor weight,
    torch::Tensor bias,
    int stride,
    int padding);
"""

conv2d_module = load_inline(
    name="conv2d_module",
    cpp_sources=conv2d_cpp_source,
    cuda_sources=conv2d_source,
    functions=["conv2d_forward_cuda"],
    verbose=False,
)


class ModelNew(nn.Module):
    def __init__(self, num_classes=1000):
        super(ModelNew, self).__init__()
        self.weight = nn.Parameter(torch.empty(96, 3, 11, 11))
        self.bias = nn.Parameter(torch.empty(96))
        nn.init.kaiming_uniform_(self.weight, a=5 ** 0.5)
        fan_in = 3 * 11 * 11
        bound = 1 / (fan_in ** 0.5)
        nn.init.uniform_(self.bias, -bound, bound)
        self.stride = 4
        self.padding = 2

    def forward(self, x):
        x = x.contiguous().cuda()
        weight = self.weight.contiguous().cuda()
        bias = self.bias.contiguous().cuda()
        return conv2d_module.conv2d_forward_cuda(x, weight, bias, self.stride, self.padding)

